#!/usr/bin/env python3
"""Generate static, indexable guide pages from schools.json. No network access."""
import json
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'boarding-schools/schools.json').read_text())
SCHOOLS=DATA['schools']
LABELS={
'ageRange':('학교 연령 범위','School age range'),'feeNotes':('학기별 요금 및 확인 사항','Termly fees and scope notes'),'location':('지역 / 카운티','Location / county'),'gender':('학교 유형','School type'),'age':('확인된 입학 연령(세)','Verified entry ages (years)'),'boarding':('기숙 / 통학 형태','Boarding / day options'),'size':('학생 수','School size'),'introduction':('학교 소개','School introduction'),'programmes':('학업 과정','Academic programmes'),'results':('시험 성적 · 연도 및 지표','Exam results · year and measure'),'destinations':('대학 진학 현황','University destinations'),'entry':('입학 가능 학년','Entry years'),'assessments':('입학 평가','Entrance assessments'),'interviews':('인터뷰','Interviews'),'application':('지원 절차','Application process'),'international':('해외 지원자 요건','International requirements'),'english':('영어 요건','English requirements'),'weekends':('주말 생활','Weekend arrangements'),'houses':('하우스 제도','House system'),'eal':('EAL 영어 지원','EAL support'),'learning':('학습 지원','Learning support'),'pastoral':('생활 및 정서 지원','Pastoral care'),'internationalSupport':('국제학생 지원','International student support'),'fees':('연간 풀보딩 학비 · GBP / 학년도','Annual full-boarding fees · GBP / academic year'),'vat':('VAT 포함 여부','VAT inclusion'),'extras':('추가 비용','Additional fees'),'activities':('스포츠 · 예술 · 음악','Sports, arts and music'),'facilities':('공식 확인 시설 및 프로그램','Verified facilities and programmes')}
def bi(ko,en):return f'<span class="lang-ko">{escape(ko)}</span><span class="lang-en">{escape(en)}</span>'
ENUMS={'girls':('여학교','Girls'), 'boys':('남학교','Boys'), 'coeducational':('남녀공학','Co-educational'), 'full':('풀보딩','Full boarding'), 'weekly':('주간 보딩','Weekly boarding'), 'flexible':('유연 보딩','Flexible boarding')}
def fact(item, key=None):
 if item['value'] is None or not item['verifiedAt'] or not item['sourceUrl']:return '<span class="school-unknown">'+bi('정보 확인 중','Not currently verified')+'</span>'
 value=item['value']
 if key=='fees': value=f'£{value:,.0f}'
 elif isinstance(value,dict): value=bi(value['ko'],value['en'])
 elif isinstance(value,list): value=', '.join(bi(*ENUMS[v]) if v in ENUMS else escape(str(v)) for v in value)
 elif value in ENUMS: value=bi(*ENUMS[value])
 else: value=escape(str(value))
 return value+f'<small class="school-source">{escape(item["academicYear"] or "")} · {escape(item["verifiedAt"])} · <a href="{escape(item["sourceUrl"],quote=True)}" target="_blank" rel="noopener noreferrer">'+bi('공식 출처','Official source')+'</a></small>'
def notice():return '<aside class="school-notice">'+bi('확인된 정보에는 공식 출처·확인일·해당 연도를 표시합니다. 미확인 항목은 추정하지 않으며 필터 대상에서 제외합니다. 학기별 학비와 연간 총액, 과정별 성적 지표를 구분해 확인해 주세요.','Verified facts include official sources, verification dates and applicable years. Unknown facts are not estimated or included in filters. Distinguish termly fees from annual totals, and compare exam results only when qualification and measures match.')+'</aside>'
def cta():return '<section class="cta-band"><div class="wrap"><h2>'+bi('우리 아이에게 맞는 학교를 찾고 계신가요?','Looking for the right school for your child?')+'</h2><p>'+bi('공식 학교 정보는 출발점입니다. 학생의 학업 수준, 영어 능력, 성향과 장기적인 진학 목표를 함께 고려한 개별 상담이 필요하다면 My EDU Prep에 문의해 주세요.','Official school information is a starting point. Contact My EDU Prep for a consultation considering your child’s academic level, English, interests and long-term goals.')+'</p><a class="button button-primary" href="/contact/">'+bi('상담 문의하기','Enquire About a Consultation')+'</a></div></section>'
def page(path,ko,en,body,mode='',school=''):
 desc=ko+' | 학교별 공식 정보 확인 및 비교 · My EDU Prep'
 text=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(ko)} | My EDU Prep</title><meta name="description" content="{escape(desc,quote=True)}"><meta property="og:title" content="{escape(ko,quote=True)} | My EDU Prep"><meta property="og:type" content="website"><meta property="og:url" content="https://myeduprep.com/{path}/"><link rel="canonical" href="https://myeduprep.com/{path}/"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/site.css?v=20260927-9"><link rel="stylesheet" href="/boarding-schools/guide.css?v=20261022-2"><script src="/site.js?v=20261022-2" defer></script><script src="/boarding-schools/data.js?v=20261022-2" defer></script><script src="/boarding-schools/guide.js?v=20261022-2" defer></script></head><body id="top" data-lang="ko" data-guide="{mode}" data-school="{school}" data-title-ko="{escape(ko,quote=True)} | My EDU Prep" data-title-en="{escape(en,quote=True)} | My EDU Prep" data-description-ko="{escape(desc,quote=True)}" data-description-en="{escape(en,quote=True)}: explore official school information with My EDU Prep."><site-header></site-header><main id="main">{body}</main><site-footer></site-footer></body></html>'''
 target=ROOT/path/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text+'\n')
def hero(ko,en,copy):return '<section class="page-hero school-hero"><div class="wrap"><p class="eyebrow light">My EDU Prep · Research guide</p><h1>'+bi(ko,en)+'</h1><p class="lead">'+copy+'</p></div></section>'
def select(key,ko,en,options):
 return '<label>'+bi(ko,en)+f'<select data-filter="{key}"><option value="">'+'전체 / All'+'</option>'+''.join(f'<option value="{escape(v,quote=True)}">{escape(t)}</option>' for v,t in options)+'</select></label>'
cards=[]
for s in SCHOOLS:
 rows=''.join('<div><dt>'+bi(*LABELS[k])+'</dt><dd>'+fact(s['facts'][k],k)+'</dd></div>' for k in ['location','gender','ageRange','boarding','programmes','fees'])
 cards.append(f'<article class="school-card" data-school-card="{s["id"]}"><div class="school-placeholder" aria-hidden="true"><span>{escape(s["name"])}</span></div><div class="school-card-body"><p class="eyebrow">School guide</p><h2><a href="/boarding-schools/{s["id"]}/">{escape(s["name"])}</a></h2><p>'+ (bi(**s['identityNote']) if s['identityNote'] else fact(s['facts']['introduction'],'introduction'))+f'</p><dl>{rows}</dl><div class="school-actions"><a class="arrow-link" href="/boarding-schools/{s["id"]}/">'+bi('학교 자세히 보기','View School Profile')+f'</a><button class="button button-outline" data-compare-add="{s["id"]}">'+bi('비교에 추가','Add to Comparison')+'</button></div></div></article>')
filters=select('location','지역 / 카운티','Location / county',[])+select('gender','학교 유형','School type',[('boys','남학교 / Boys'),('girls','여학교 / Girls'),('coeducational','남녀공학 / Co-educational')])+select('age','입학 연령','Entry age',[(str(n),str(n)) for n in range(7,19)])+select('programmes','학업 과정','Academic programme',[(x,x) for x in ['GCSE','A-Level','IB','BTEC']])+select('fees','연간 풀보딩 학비','Annual full-boarding fees',[('0-40000','≤ £40,000'),('40000-60000','£40,000–£60,000'),('60000-999999','£60,000+')])+select('boarding','기숙 형태','Boarding type',[('full','풀보딩 / Full'),('weekly','주간 보딩 / Weekly'),('flexible','유연 보딩 / Flexible')])
body=hero('영국 보딩스쿨 가이드','British Boarding School Guide',bi('학교의 명성보다 중요한 것은 우리 아이에게 맞는 교육 환경입니다. 영국 보딩스쿨의 학업 과정, 학비, 기숙사 생활, 입학 요건을 한눈에 살펴보고 비교해 보세요.','Explore and compare British boarding schools by academic programmes, fees, boarding arrangements and admissions requirements.'))+'<section class="section-tight"><div class="wrap">'+notice()+'<form class="school-filters" data-school-filters><label class="school-search">'+bi('학교 이름 검색','Search by school name')+'<input type="search" data-filter="search" autocomplete="off"></label>'+filters+'<button type="reset" class="button button-outline">'+bi('필터 초기화','Clear Filters')+'</button></form><p data-results-count role="status"></p><p data-no-results hidden>'+bi('조건에 맞는 공식 확인 정보가 없습니다. 필터를 초기화하면 모든 학교를 볼 수 있습니다.','No officially verified information matches these filters. Clear filters to view all schools.')+'</p><div class="school-grid">'+''.join(cards)+'</div><noscript><p>'+bi('검색 및 비교 기능은 JavaScript가 필요합니다. 학교별 페이지는 아래 링크에서 확인할 수 있습니다.','Search and comparison require JavaScript. School profiles remain available through the links.')+'</p></noscript><div class="school-selection"><p data-selection-summary role="status"></p><a class="button button-primary" data-compare-link href="/boarding-schools/compare/">'+bi('선택한 학교 비교하기','Compare selected schools')+'</a><p data-selection-feedback role="status"></p></div></div></section>'+cta()
page('boarding-schools','영국 보딩스쿨 가이드','British Boarding School Guide',body,'directory')
for s in SCHOOLS:
 sections=[]
 for ko,en,keys in [('학교 개요','School overview',['location','gender','ageRange','age','boarding','size','introduction']),('학업 과정','Academic programmes',['programmes','results','destinations']),('입학 안내','Admissions',['entry','assessments','interviews','application','international','english']),('기숙사 생활','Boarding life',['boarding','weekends','houses','internationalSupport']),('학생 지원','Student support',['eal','learning','pastoral','internationalSupport']),('학비 및 활동','Fees and activities',['fees','feeNotes','vat','extras','activities','facilities'])]:
  sections.append('<section class="school-profile-section"><h2>'+bi(ko,en)+'</h2><dl class="school-facts">'+''.join('<div><dt>'+bi(*LABELS[k])+'</dt><dd>'+fact(s['facts'][k],k)+'</dd></div>' for k in keys)+'</dl></section>')
 body=hero(s['name'],s['name'],bi('영국 보딩스쿨 가이드 · 학교별 정보','British Boarding School Guide · School profile'))+'<section class="section-tight"><div class="wrap school-profile"><a class="arrow-link" href="/boarding-schools/">'+bi('전체 학교 목록','All schools')+'</a>'+notice()+(('<p>'+bi(**s['identityNote'])+'</p>') if s['identityNote'] else '')+''.join(sections)+f'<section class="school-profile-section"><h2>'+bi('공식 출처','Official sources')+f'</h2><p><a class="arrow-link" href="{s["website"]}" target="_blank" rel="noopener noreferrer">{escape(s["name"])} ↗</a></p><p>'+bi('공식 자료를 직접 검토한 항목에는 출처와 확인일을 표시했습니다. 내용은 변경될 수 있으므로 지원 전 학교에 재확인하세요. 미확인 항목은 정보 확인 중으로 표시합니다.','Reviewed facts show their official source and verification date. Details can change; reconfirm with the school before applying. Unverified fields are labelled accordingly.')+'</p></section><div class="school-actions"><button class="button button-primary" data-compare-add="'+s['id']+'">'+bi('학교 비교하기','Compare This School')+'</button><a class="button button-outline" data-compare-link href="/boarding-schools/compare/">'+bi('비교표 열기','Open comparison')+'</a><a class="arrow-link" href="/contact/">'+bi('상담 문의하기','Enquire About a Consultation')+'</a></div><p data-selection-feedback role="status"></p></div></section>'
 page('boarding-schools/'+s['id'],s['name']+' 학교 안내',s['name']+' profile',body,'profile',s['id'])
body=hero('학교 비교하기','Compare schools',bi('최대 3개 학교를 나란히 살펴보세요. 모바일에서는 2개 학교씩 비교하면 읽기 편합니다.','Compare up to three schools side by side. On mobile, select two schools for a more comfortable view.'))+'<section class="section-tight"><div class="wrap">'+notice()+'<a class="arrow-link" href="/boarding-schools/">'+bi('학교 목록으로 돌아가기','Back to the school directory')+'</a><div class="school-compare-picker"><label for="school-picker">'+bi('학교 추가','Add a school')+'</label><select id="school-picker"><option value="">'+'학교 선택 / Select a school'+'</option>'+''.join(f'<option value="{s["id"]}">{escape(s["name"])}</option>' for s in SCHOOLS)+'</select><button class="button button-outline" data-picker-add>'+bi('추가하기','Add school')+'</button><button class="button button-outline" data-share>'+bi('비교 링크 복사','Copy comparison link')+'</button></div><p data-selection-feedback role="status"></p><p data-compare-empty>'+bi('비교할 학교를 위에서 선택해 주세요.','Choose schools above to start comparing.')+'</p><p class="school-mobile-tip">'+bi('표를 좌우로 스크롤하여 선택한 학교를 모두 확인할 수 있습니다.','Scroll the table horizontally to view all selected schools.')+'</p><div class="school-table-scroll" tabindex="0" role="region" aria-label="학교 비교 / School comparison"><table class="school-compare-table"><caption class="sr-only">'+bi('선택한 학교 비교','Selected school comparison')+'</caption><thead></thead><tbody></tbody></table></div><noscript>'+bi('비교 도구를 사용하려면 JavaScript를 켜 주세요.','Enable JavaScript to use the comparison tool.')+'</noscript></div></section>'+cta()
page('boarding-schools/compare','영국 보딩스쿨 비교','Compare British boarding schools',body,'compare')
(ROOT/'boarding-schools/data.js').write_text('/* Generated by scripts/build-boarding-schools.py; edit schools.json. */\nwindow.MEP_SCHOOLS = '+json.dumps(SCHOOLS,ensure_ascii=False)+';\nwindow.MEP_SCHOOL_LABELS = '+json.dumps(LABELS,ensure_ascii=False)+';\n')
p=ROOT/'sitemap.xml';text=p.read_text();text='\n'.join(line for line in text.splitlines() if '/boarding-schools' not in line);text=text.replace('</urlset>',''.join(f'  <url><loc>https://myeduprep.com/boarding-schools/{suffix}</loc><priority>0.7</priority></url>\n' for suffix in ['', 'compare/']+[s['id']+'/' for s in SCHOOLS])+'</urlset>');p.write_text(text+'\n')
print('Generated directory, comparison and eight school profiles.')
